TLM.f("Tempora/Pasc0-5",{"officium":"Die VI infra octavam Paschæ","rule":["ex Pasc0-0;","Credo","Sequentia","Suffr=Ecclesiæ,Papa;;"],"ruleInherited":["Sequentia","Credo","Prefatio=Pasch"],"fallback":"Tempora/Pasc0-0","sections":{"Introitus":[{"k":"ref","la":"Ps 77:53"},{"k":"text","la":"Edúxit eos Dóminus in spe, allelúja: et inimícos eórum opéruit mare, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Atténdite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Edúxit eos Dóminus in spe, allelúja: et inimícos eórum opéruit mare, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui paschále sacraméntum in reconciliatiónis humánæ fœ́dere contulísti: da méntibus nostris; ut, quod professióne celebrámus, imitémur efféctu."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Petri 3:18-22"},{"k":"text","la":"Caríssimi: Christus semel pro peccátis nostris mórtuus est, justus pro injústis, ut nos offérret Deo, mortificátus quidem carne, vivificátus autem spíritu. In quo et his, qui in cárcere erant, spirítibus véniens prædicávit: qui incréduli fúerant aliquándo, quando exspectábant Dei patiéntiam in diébus Noë, cum fabricarétur arca, in qua pauci, id est octo ánimæ salvæ factæ sunt per aquam. Quod et vos nunc símilis formæ salvos facit baptísma: non carnis deposítio sórdium, sed consciéntiæ bonæ interrogátio in Deum per resurrectiónem Jesu Christi, Dómini nostri, qui est in dextera Dei."}],"Graduale":[{"k":"ref","la":"Ps 117:24; 117:26-27"},{"k":"text","la":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea."},{"k":"text","la":"Benedíctus, qui venit in nómine Dómini: Deus Dóminus, et illúxit nobis.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 95:10"},{"k":"text","la":"Dícite in géntibus: quia Dóminus regnávit a ligno."}],"Sequentia":[{"k":"text","la":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","la":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","la":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","la":"Dic nobis, María, quid vidísti in via?"},{"k":"text","la":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","la":"Angélicos testes, sudárium et vestes."},{"k":"text","la":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","la":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","la":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 28:16-20"},{"k":"text","la":"In illo témpore: Undecim discípuli abiérunt in Galilǽam, in montem, ubi constitúerat illis Jesus. Et vidéntes eum adoravérunt: quidam autem dubitavérunt. Et accédens Jesus locútus est eis, dicens: Data est mihi omnis potéstas in cœlo, et in terra. Eúntes ergo, docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti: docéntes eos serváre ómnia, quæcúmque mandávi vobis. Et ecce, ego vobíscum sum ómnibus diébus usque ad consummatiónem sǽculi."}],"Offertorium":[{"k":"ref","la":"Exod 12:14"},{"k":"text","la":"Erit vobis hæc dies memoriális, allelúja: et diem festum celebrábitis solémnem Dómino in progénies vestras: legítimum sempitérnum diem, allelúja, allelúja, allelúja."}],"Secreta":[{"k":"text","la":"Hóstias, quǽsumus, Dómine, placátus assúme: quas et pro renatórum expiatióne peccáti deférimus, et pro acceleratióne cœléstis auxílii."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 28:18-19"},{"k":"text","la":"Data est mihi omnis potéstas in cœlo et in terra, allelúja: eúntes, docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Réspice, quǽsumus, Dómine, pópulum tuum: et, quem ætérnis dignátus es renováre mystériis, a temporálibus culpis dignánter absólve."},{"k":"macro","name":"Per Dominum"}]},"hr":{"dbe987e8409132fb":{"t":"Ps 77, 53, Ps 77, 1\n(Ps 77, 53) Sigurno ih je vodio Gospodin, <i>aleluja</i>,\na neprijatelje je njihove pokrilo more, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 77, 1). Pazi, puče moj, na zakon moj, čuj riječi usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 77, 53) Sigurno ih je vodio Gospodin, <i>aleluja</i>,\na neprijatelje je njihove pokrilo more, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 77, 53). Sigurno ih je vodio Gospodin, aleluja, a neprijatelje je njihove pokrilo more, ale- t T. j. mojim apostolima. luja, aleluja, aleluja. (Ps. 77, 1) Pazi, puče moj, na zakon moj, čuj riječ usta mojih. Slava Ocu . . . Sigurno ...","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"4847ca4097295945":{"t":"<i>Pomolimo se</i>.\nSvemogući, vječni Bože, koji si ustanovio uskrsna otajstva za pomirenje ljudskog roda, daj dušama našim da izvršujemo činom što priznavanjem svetkujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Mo.litva. Svemoigući, vječnii Bože, koji si ustanovio vazmene tajne za pomirenje ljudskog roda, daj dušama našim, da izvršujemo činom, što priznavanjem svetkujemo, po G. n.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"9d9c3ce20b7f78c6":{"t":"1 Pt 18-22\nČitanje Poslanice bl. Petra apostola. Predragi! Krist je jedanput za grijehe naše umro, pravedan za nepravedne da nas privede Bogu, ubijen doduše tijelom, ali oživljen Duhom. U njemu je sišao i propovijedao dušama koje bijahu u tamnici. One nekada nisu vjerovale kad ih je iščekivala Božja strpljivost u vrijeme Noino, kad se gradio kovčeg u kojem se malo to jest osam duša spasilo od vode. Slično i vas sada spašava krštenje koje nije pranje nečistoće tjelesne, nego zavjet dobre savjesti Bogu uskrsnućem Isusa Krista koji sjedi s desne strane Bogu.","kn":"Čitanje poslanice bl. Petra apostola (I, 3, 18-22). Predragi! Krist je jeda.niput .za grijehe naše umro, pravedan za nepravedne, da nas privede Bogu, ubijen doduše tijelom, ali oživljen Duhom. U njemu je sišao i propovijedao dušama, koje bijahu u tamnici. One nekada nisu vjerovale, kad ih je iščekivala 'strpljivost Božja u vrijeme Nojino, kad se gradio kovčeg, u kojem se malo, to jest osam duša, spasilo vodom. Slično i vas sada spasava, krštenjem, koje nije pranje nečistoće tjelesne, nego zavjet dobre savjesti Bogu, uskrsnućem Isusa Krista, koji je s desne strane Bogu.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"5de56423dcc34a53":{"t":"Ps 117, 24 i 26-27\nOvo je dan što ga učini Gospodin, Kličimo i radujmo se danas. Blagoslovljen koji dolazi u ime Gospodnje, Bog je Gospodin, on nas je obasjao.\n\nPs 95, 10\n<i>Aleluja</i>, <i>aleluja</i>.\nRecite narodima da Gospodin kraIjuje s drveta.","kn":"(Ps. 117, 24-27). Ovo je dan, koji nam je pripravio Gospodin, kličimo i radujmo se. Blagoslovljen, koji dolazi u ime Gospodnje, Bog je Gospođin, on nas je obasjao.\n\nAleluja, aleluja (Ps. 95, 10). Recite narodima, da Gospodin kraljuje s drveta.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"a670bd50efcad44c":{"t":"Svetoj Žrtvi uskrsnici dajte slavu krštenici!<i>\n</i>\nJanje ovce oslobodi Krist nas grješne preporodi.<i>\n</i>\nSa životom smrt se sasta i čudesna borba nasta: Vođa živih pade tada i živ živcat opet vlada.<i>\n</i>\nMarijo, o reci što je? Što ti oko vidjelo je?<i>\n</i>\nGrob ja vidjeh Krista Boga, svijetlu slavu uskrsloga.<i>\n</i>\nAnđele i platno bijelo u kom bješe sveto tijelo.<i>\n</i>\nUfanje mi uskrslo je Krist, moj Gospod i sve moje! Pred vama će tamo gdje je cvjetna strana Galileje.<i>\n</i>\nZnamo da si doistine uskrsnuo Božji Sine! Pobjedniče, Kralju divan, budi nama milostivan!<i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"2970b8470c8f5d84":{"t":"Mt 28, 16-20\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme pođe jedanaestorica učenika u Galileju na goru kamo im zapovjedi Isus. I kad ga vidješe, pokloniše mu se, a jedni posumnjaše. Tada pristupi Isus i reče: Dana mi je sva vlast na nebu i na zemlji. Idite dakle i naučavajte sve narode krsteći ih u ime Oca i Sina i Duha Svetoga. Učite ih da drže sve što sam vam zapovjedio. I evo: ja sam s vama u sve dane do svršetka svijeta.","kn":"t Slijedi sv. evanđelje po Mateju (28, 16-20). U ono vrijeme pođe jedanaestorica učenika u Galileju na goru, kamo im zapovjedi Isus. I kad ga vidješe, pokloniše mu se, a jedni posumnjaše. Tada pristupi Isus i reče: Dana mi je sva vlast na nebu i na zemlji. Idite dakle i naučavajte sve narode krsteći ih u ime Oca i Sina i Duha svetoga; učeći ih, da drže sve, što sam vam zapovjedio. I evo . ja sam s vama u sve dane do svršetka svijeta.","knRef":"Kniewald 1942, str. 312–313 (snimka 157) (OCR)"},"7ad746f665c41746":{"t":"Izl 12, 14\nBit će vam ovaj dan za spomen, <i>aleluja</i>,\nda svetkujete svečani dan, posvećen Gospodinu, od koljena do koljena, dan svečani dovijeka, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Izl. 12, 14). Bit će vam dan za spomen, aleluja; da svetkujete svečani dan, posvećen Gospodinu, od koljena do koljena, dan svečani dovijeka, aleluja, aleluja, aleluja.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"5cc850454c559476":{"t":"Primi, Gospodine, umilostivljen žrtve koje ti prinosimo i za okajanje grijeha preporođenih i za ubrzanje nebeske pomoći.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gos/podine, umilostivljen žrtve, koje Ti prinosimo i za oka janje grijeha preporođenih i za ubrzanje nebeske pomoći, po G. n.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"687cae1ead8b8c38":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>danas</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"cacdef4719b04695":{"t":"Mt 28, 18-19\nDana mi je sva vlast na nebu i na zemlji, <i>aleluja</i>.\nIdite i naučavajte sve narode krsteći ih u ime Oca i Sina i Duha Svetoga, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Mt. 28, 18, 19). Dana mi je sva vlast na nebu i na zemlji, aleluja: , idite i naučajte sve narode krsteći ih u ime Oca i Sina i Duha Svetoga, aleluja, aleluja.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"5566ddca445a7472":{"t":"<i>Pomolimo se</i>.\nPogledaj, molimo, Gospodine, na puk svoj i milostivo ga odriješi od vremenitih krivica, jer si ga se dostojao obnoviti vječnim tajnama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, molimo, Gospodine, na Puk svoj i milostivo ga Oidriješi od vremenitih krivica, jer si ga se dostojao obnoviti vječnim tajnama.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"}}});
